<template>
  <div class="homeWrap">
    <div class="topBox">
      <div class="leftBox">
        <div class="text">{{ dateStr }}</div>
        <div class="text">{{ dateWeek }}</div>
        <div class="time">{{ dateTime }}</div>

        <div class="btn" @click="settingFn()" v-if="showImport">模型配置</div>

        <div class="btn" @click="batchFn()" v-if="showImport">数据管理</div>

        <el-upload
          accept=".xlsx, .xls"
          multiple
          :limit="20"
          :show-file-list="false"
          :auto-upload="false"
          :file-list="fileList"
          :on-change="httpRequest"
          :on-exceed="handleExceed"
          action=""
        >
          <el-button
            type="primary"
            style="margin-left: 10px"
            v-if="showImport"
            :loading="uploadLoading"
            >点击上传</el-button
          >
        </el-upload>
      </div>
    </div>
    <div class="rightBox">
      <div
        class="btn"
        :class="{ active: tabIndex == 1 }"
        @click="changeTab(1)"
        :style="{
          'z-index':
            dialogShow || dialogLoading1 || modelDialog ? '30' : '3000',
        }"
      >
        模型监控
      </div>
      <div
        class="btn"
        :class="{ active: tabIndex == 2 }"
        @click="changeTab(2)"
        :style="{
          'z-index':
            dialogShow || dialogLoading1 || modelDialog ? '30' : '3000',
        }"
      >
        趋势概览
      </div>
      <div
        class="timeBox"
        :style="{
          'z-index':
            dialogShow || dialogLoading1 || modelDialog ? '30' : '3000',
        }"
      >
        <!-- <el-date-picker
          v-show="tabIndex == 1"
          v-model="dataTime"
          type="month"
          :clearable="false"
          format="yyyy年MM月"
          value-format="yyyy/MM"
          placeholder="选择月份"
          @change="changeTab(1)"
        >
        </el-date-picker> -->
        <el-date-picker
          v-show="tabIndex == 1"
          v-model="dataTime"
          type="monthrange"
          range-separator="-"
          :clearable="false"
          format="yyyy/MM"
          value-format="yyyy/MM"
          start-placeholder="开始月份"
          end-placeholder="结束月份"
          @change="changeTab(1)"
        >
        </el-date-picker>
        <el-date-picker
          v-show="tabIndex == 2"
          v-model="dataTimeArr"
          type="monthrange"
          range-separator="-"
          :clearable="false"
          format="yyyy/MM"
          value-format="yyyy/MM"
          start-placeholder="开始月份"
          end-placeholder="结束月份"
          @change="changeTab(2)"
        >
        </el-date-picker>
      </div>
    </div>

    <div class="pageContentWrap">
      <div class="contentBox">
        <div class="row">
          <div class="col col1" v-loading="arrLoading1">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn1"
              :echartId="'bigEchart1'"
              ref="bigEchartRef1"
              @finished="finished('bigEchartRef1', arr1, '总览')"
            ></Echarts>
          </div>
          <div class="col col2" v-loading="arrLoading2">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn2"
              :echartId="'bigEchart2'"
              ref="bigEchartRef2"
              @finished="
                finished('bigEchartRef2', arr2, '贷款业务全流程风险监测模型')
              "
            ></Echarts>
          </div>
          <div class="col col3" v-loading="arrLoading3">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn3"
              :echartId="'bigEchart3'"
              ref="bigEchartRef3"
              @finished="
                finished('bigEchartRef3', arr3, '存款业务风险监测模型')
              "
            ></Echarts>
          </div>
        </div>
        <div class="row">
          <div class="col col4" v-loading="arrLoading4">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn4"
              :echartId="'bigEchart4'"
              ref="bigEchartRef4"
              @finished="
                finished('bigEchartRef4', arr4, '资产质量风险监测模型')
              "
            ></Echarts>
          </div>
          <div class="col col5" v-loading="arrLoading5">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn5"
              :echartId="'bigEchart5'"
              ref="bigEchartRef5"
              @finished="
                finished('bigEchartRef5', arr5, '合规与操作风险监测模型')
              "
            ></Echarts>
          </div>
          <div class="col col6" v-loading="arrLoading6">
            <Echarts
              class="bigEchats"
              :echartWidth="'calc(98%)'"
              :echartHeight="'calc(100%)'"
              :echartOptions="getOptionFn6"
              :echartId="'bigEchart6'"
              ref="bigEchartRef6"
              @finished="
                finished(
                  'bigEchartRef6',
                  arr6,
                  '区域与行业专项风险（场景化类）'
                )
              "
            ></Echarts>
          </div>
        </div>
        <div class="row row1" v-loading="tableLoading">
          <div class="tableWrap">
            <el-table :data="tableData" height="100%" style="width: 100%">
              <el-table-column label="排名" width="80" align="center">
                <template slot-scope="scope">
                  <div class="indexBox">
                    <span>{{
                      (pageNum - 1) * pageSize + scope.$index + 1
                    }}</span>
                  </div>
                </template>
              </el-table-column>
              <el-table-column prop="机构名称" label="机构名称">
                <template slot-scope="scope">
                  <div class="nameText">
                    <span>{{ scope.row["机构名称"] }}</span>
                  </div>
                </template>
              </el-table-column>
              <el-table-column
                prop="机构编码"
                label="机构编码"
              ></el-table-column>
              <el-table-column
                prop="模型类型1记录数"
                label="贷款业务全流程风险监测模型(个)"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型1记录数'] > 0"
                    @click="
                      downDetail(1, scope.row, '贷款业务全流程风险监测模型')
                    "
                  >
                    <span>{{ scope.row["模型类型1记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型1记录数"] }}</span>
                </template>
              </el-table-column>
              <el-table-column
                prop="模型类型2记录数"
                label="存款业务风险监测模型(个)"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型2记录数'] > 0"
                    @click="downDetail(2, scope.row, '存款业务风险监测模型')"
                  >
                    <span>{{ scope.row["模型类型2记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型2记录数"] }}</span>
                </template>
              </el-table-column>
              <el-table-column
                prop="模型类型3记录数"
                label="资产质量风险监测模型(个)"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型3记录数'] > 0"
                    @click="downDetail(3, scope.row, '资产质量风险监测模型')"
                  >
                    <span>{{ scope.row["模型类型3记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型3记录数"] }}</span>
                </template>
              </el-table-column>
              <el-table-column
                prop="模型类型4记录数"
                label="合规与操作风险监测模型(个)"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型4记录数'] > 0"
                    @click="downDetail(4, scope.row, '合规与操作风险监测模型')"
                  >
                    <span>{{ scope.row["模型类型4记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型4记录数"] }}</span>
                </template>
              </el-table-column>
              <el-table-column
                prop="模型类型5记录数"
                label="区域与行业专项风险(场景化类)(个)"
                align="center"
              >
                <template slot-scope="scope">
                  <div
                    class="clickText"
                    v-if="scope.row['模型类型5记录数'] > 0"
                    @click="
                      downDetail(5, scope.row, '区域与行业专项风险(场景化类)')
                    "
                  >
                    <span>{{ scope.row["模型类型5记录数"] }}</span>
                  </div>
                  <span v-else>{{ scope.row["模型类型5记录数"] }}</span>
                </template>
              </el-table-column>
            </el-table>
          </div>
        </div>
      </div>
    </div>

    <!-- 下钻弹窗 -->
    <el-dialog
      :visible.sync="dialogVisible"
      width="100%"
      top="11vh"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose"
    >
      <div class="dialogWrap">
        <div class="dialogName">{{ dialogName }}</div>
        <Echarts
          v-loading="downDetailLoading"
          class="bigEchats"
          :echartWidth="'calc(94%)'"
          :echartHeight="'calc(94%)'"
          :echartOptions="getDialogOption"
          :echartId="'dialogEchart'"
          ref="dialogEchart"
          @finished="finished('dialogEchart', [], '', true)"
        ></Echarts>
      </div>
    </el-dialog>

    <!-- 详情弹窗 -->
    <el-dialog
      :visible.sync="dialogShow"
      width="100%"
      top="11vh"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="dialogWrap">
        <div class="dialogName">{{ dialogName1 }}</div>

        <div class="detailWrap" v-loading="dialogLoading1">
          <div class="seekBox">
            <el-form :inline="true" :model="seekForm">
              <el-form-item label="机构：">
                <el-select
                  v-model="seekForm.orgId"
                  placeholder="选择机构"
                  filterable
                  clearable
                  @change="getDetailFn"
                >
                  <el-option
                    v-for="item in orgList"
                    :key="item.jgbm+ 'jj'"
                    :label="item.jgmc"
                    :value="item.jgbm"
                  >
                  </el-option>
                </el-select>
              </el-form-item>
              <el-form-item label="日期：">
                <el-date-picker
                  v-model="seekForm.time"
                  type="monthrange"
                  range-separator="-"
                  :clearable="false"
                  format="yyyy/MM"
                  value-format="yyyy/MM"
                  start-placeholder="开始月份"
                  end-placeholder="结束月份"
                  @change="getDetailFn"
                >
                </el-date-picker>

                <!-- <el-date-picker
                  v-model="seekForm.time"
                  type="month"
                  format="yyyy-MM"
                  value-format="yyyy-MM"
                  :clearable="false"
                  placeholder="选择日期"
                  @change="getDetailFn"
                >
                </el-date-picker> -->
              </el-form-item>
              <el-form-item label="模型：">
                <el-select
                  v-model="seekForm.modelName"
                  placeholder="选择模型"
                  filterable
                  @change="changeModel"
                >
                  <el-option
                    v-for="item in modelList"
                    :key="item.model_name + 'gg'"
                    :label="item.model_name"
                    :value="item.model_name"
                  >
                  </el-option>
                </el-select>
              </el-form-item>
            </el-form>

            <!-- <div
              class="downBtn"
              @click="getExportFn()"
              v-loading="exportLoading"
            >
              导出
            </div> -->
          </div>
          <div class="tableBox">
            <el-table
              :data="detailArr"
              height="calc(100% - 60px)"
              style="width: 100%"
            >
              <el-table-column
                :prop="`KPI_VAL${index}`"
                :label="item"
                min-width="100"
                v-for="(item, index) in detailHeader"
                :key="index + 'sd'"
              ></el-table-column>
            </el-table>
            <el-pagination
              @size-change="sizeChange"
              @current-change="currentChange"
              :current-page="pageNum"
              :page-sizes="[20, 50, 100, 200]"
              :page-size="pageSize"
              layout="total, sizes, prev, pager, next, jumper"
              :total="total"
            >
            </el-pagination>
          </div>
        </div>
      </div>
    </el-dialog>

    <!-- 模型配置 -->
    <el-dialog
      :visible.sync="modelDialog"
      width="100%"
      top="11vh"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="dialogWrap">
        <div class="dialogName">模型配置</div>

        <div class="detailWrap">
          <div class="seekBox">
            <el-form
              :inline="true"
              :model="seekForm1"
              :rules="rules"
              ref="modelConfig"
            >
              <el-form-item label="模型：">
                <el-select
                  v-model="seekForm1.modelName"
                  placeholder="选择模型"
                  filterable
                  @change="getModelConfigFn"
                >
                  <el-option
                    v-for="item in modelList"
                    :key="item.model_name + '13'"
                    :label="item.model_name"
                    :value="item.model_name"
                  >
                  </el-option>
                </el-select>
              </el-form-item>

              <el-form-item label="模型类别（必选）：" prop="modelType">
                <el-select
                  v-model="seekForm1.modelType"
                  placeholder="选择模型"
                  filterable
                >
                  <el-option
                    v-for="item in modeTypelList"
                    :key="item.value+'66'"
                    :label="item.label"
                    :value="item.value"
                  >
                  </el-option>
                </el-select>
              </el-form-item>
            </el-form>
          </div>
          <div class="tableBox" v-loading="dialogLoading2">
            <el-table
              :data="modelTableList"
              height="calc(100% - 80px)"
              style="width: 100%"
            >
              <el-table-column prop="model_name" label="模型字段">
                <template slot-scope="scope">
                  <span>{{ scope.row.model_name }}</span>
                </template>
              </el-table-column>
              <el-table-column prop="model_name_des" label="模型字段中文">
                <template slot-scope="scope">
                  <el-input
                    v-model="scope.row.model_name_des"
                    clearable
                    placeholder="请输入模型字段中文"
                  ></el-input>
                </template>
              </el-table-column>
              <el-table-column prop="model_name_disable" label="是否展示">
                <template slot-scope="scope">
                  <el-switch
                    v-model="scope.row.model_name_disable"
                    inactive-value="0"
                    active-value="1"
                    active-color="#13ce66"
                    inactive-color="#ff4949"
                  >
                  </el-switch>
                </template>
              </el-table-column>
            </el-table>

            <div class="btnBox">
              <el-button
                type="primary"
                @click="settingConfirmFn()"
                :loading="dialogLoading2"
                >确定</el-button
              >
              <el-button @click="modelDialog = false">关闭</el-button>
            </div>
          </div>
        </div>
      </div>
    </el-dialog>

    <!-- 数据管理 -->
    <el-dialog
      :visible.sync="batchDialog"
      width="100%"
      top="11vh"
      :modal-append-to-body="false"
      :close-on-click-modal="false"
      @close="dialogClose1"
    >
      <div class="dialogWrap">
        <div class="dialogName">数据管理</div>

        <div class="detailWrap">
          <div class="seekBox">
            <el-form
              :inline="true"
              :model="seekForm2"
              ref="dataConfig"
            >
              <el-form-item label="模型名称：">
                <el-select
                  v-model="seekForm2.model_name"
                  placeholder="选择模型"
                  filterable
                  clearable
                  @change="batchFn()"
                >
                  <el-option
                    v-for="item in modelAllList"
                    :key="item.model_name + 'cc'"
                    :label="item.model_name"
                    :value="item.model_name"
                  >
                  </el-option>
                </el-select>
              </el-form-item>

              <el-form-item label="机构名称：">
                <el-select
                  v-model="seekForm2.jgbm"
                  placeholder="选择模型"
                  filterable
                  clearable
                   @change="batchFn()"
                >
                  <el-option
                    v-for="item in orgAllList"
                    :key="item.jgbm + item.jgmc + 'dd'"
                    :label="item.jgmc"
                    :value="item.jgbm"
                  >
                  </el-option>
                </el-select>
              </el-form-item>

               <el-button
                  style="float: right;margin-right:30px"
                  :loading="removeMoreLoading"
                  :disabled="multipleSelection.length == 0"
                  type="danger"
                  @click="removeBatchFn()"
                  >批量删除</el-button
                >
            </el-form>
          </div>
          <div class="tableBox" height="100%" v-loading="batchLoading">
            <el-table
              :data="batchList"
              height="100%"
              style="width: 100%"
              @selection-change="handleSelectionChange"
              @sort-change="sortChange"
            >
              <el-table-column type="selection" width="55"> </el-table-column>
              <el-table-column
                prop="model_name"
                label="模型名称"
                min-width="120px"
                sortable="custom"
              ></el-table-column>
              <el-table-column
                prop="jgmc"
                label="机构名称"
                min-width="120px"
                sortable="custom"
              ></el-table-column>
              <el-table-column
                prop="count"
                label="数量"
                min-width="100px"
                sortable="custom"
              ></el-table-column>
              <el-table-column
                prop="create_time"
                label="创建时间"
                min-width="140px"
                sortable="custom"
              ></el-table-column>
              <el-table-column
                prop="batch_no"
                label="文件名称"
                min-width="200px"
              ></el-table-column>
              <el-table-column label="操作" min-width="80px">
                <template slot-scope="scope">
                  <el-button
                    :loading="scope.row.removeLoading"
                    type="danger"
                    @click="removeBatchFn(scope.row)"
                    >删除</el-button
                  >
                </template>
              </el-table-column>
            </el-table>
          </div>
        </div>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import { chunk } from "lodash";

import { mapState } from "vuex";

import {
  getChartData,
  getOrgTypeStats,
  getOrgTypeStats2,
  getChartDataMonthly,
  getDetail,
  getModelList,
  getOrgList,
  getDataAll,
  getDataMonthlyAll,
  getExport,
  getModelConfig,
  getModelConfigUpd,
  getBatchStats,
  getBatchDelete,
  getImport,
} from "@/api/home";

import Echarts from "@/components/echarts.vue";

let timer = null;

export default {
  name: "HomeView",
  data() {
    return {
      seekForm2: {},
      multipleSelection: [],
      removeMoreLoading: false,
      modelAllList: [],
      orgAllList: [],

      dateStr: "",
      dateWeek: "",
      dateTime: "",

      tabIndex: 1,

      dataTime: [],
      dataTimeArr: [],

      arr1: [],
      arr2: [],
      arr3: [],
      arr4: [],
      arr5: [],
      arr6: [],
      dialogArr: [],
      dialogName: "",
      arrLoading1: false,
      arrLoading2: false,
      arrLoading3: false,
      arrLoading4: false,
      arrLoading5: false,
      arrLoading6: false,
      tableLoading: false,

      dialogVisible: false,
      dialogLoading: false,

      tableData: [],

      dialogShow: false,
      dialogLoading1: false,
      dialogName1: "",
      detailHeader: [],
      detailArr: [],
      total: 0,
      pageNum: 1,
      pageSize: 20,

      seekForm: {},
      modelList: [],
      orgList: [],
      exportLoading: false,
      showImport: this.$route.query.import,
      uploadLoading: false,

      downDetailLoading: false,
      downDetailParams: {},
      modelDialog: false,
      seekForm1: {},
      dialogLoading2: false,
      modelTableObj: {},
      modelTableList: [],

      batchDialog: false,
      batchLoading: false,
      batchList: [],

      modeTypelList: [
        {
          label: "贷款业务全流程风险监测模型",
          value: "1",
        },
        {
          label: "存款业务风险监测模型",
          value: "2",
        },
        {
          label: "资产质量风险监测模型",
          value: "3",
        },
        {
          label: "合规与操作风险监测模型",
          value: "4",
        },
        {
          label: "区域与行业专项风险（场景化类）",
          value: "5",
        },
      ],
      rules: {
        modelType: [
          { required: true, message: "请选择模型类别", trigger: "change" },
        ],
      },
      fileList: [],
    };
  },
  computed: {
    ...mapState({
      calcHieght: (state) => state.calcHieght,
    }),
    getDialogOption() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.dialogArr, this.dialogIndex, true);
      } else {
        return this.getLineOptions(this.dialogArr, true);
      }
    },
    getOptionFn1() {
      if (this.tabIndex == "1") {
        return this.getPieOptions(this.arr1);
      } else {
        return this.getLineOptions(this.arr1);
      }
    },
    getOptionFn2() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr2, "2");
      } else {
        return this.getLineOptions(this.arr2);
      }
    },
    getOptionFn3() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr3, "3");
      } else {
        return this.getLineOptions(this.arr3);
      }
    },
    getOptionFn4() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr4, "4");
      } else {
        return this.getLineOptions(this.arr4);
      }
    },
    getOptionFn5() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr5, "5");
      } else {
        return this.getLineOptions(this.arr5);
      }
    },
    getOptionFn6() {
      if (this.tabIndex == "1") {
        return this.getBarOptions(this.arr6, "6");
      } else {
        return this.getLineOptions(this.arr6);
      }
    },
    getDetailParams() {
      return {
        modelName: this.dialogName1,
        // month: (this.seekForm.time || "").replace("-", ""),
        ...this.getParams(this.seekForm.time || []),
        jgbm: this.seekForm.orgId || "",
        page: this.pageNum,
        per_page: this.pageSize,
      };
    },
  },
  components: {
    Echarts,
  },
  created() {
    this.getDateTimeFn(true);
    setInterval(() => {
      this.getDateTimeFn();
    }, 1000);

    this.changeTab(1);
  },
  methods: {
    handleExceed(files, fileList) {
      this.$message.warning(
        `当前限制选择 20 个文件，本次选择了 ${files.length} 个文件`
      );
    },

    handleSelectionChange(val) {
      this.multipleSelection = val;
    },

    sortChange(event) {
      let pxfsStr = "desc";
      if (event["order"] == "ascending") {
        pxfsStr = "asc";
      } else if (event["order"] == "descending") {
        pxfsStr = "desc";
      }

      this.batchFn(event["prop"], pxfsStr)
    },

    httpRequest(file, fileList) {
      if (timer) {
        clearTimeout(timer);
      }
      timer = setTimeout(() => {
        this.getImportFn(fileList);
      }, 300);
    },

    async getImportFn(fileList) {
      this.uploadLoading = true;
      let params = new FormData();
      fileList.forEach((obj) => {
        params.append("file", obj.raw);
      });

      let res = await getImport(params);

      if (res.code == 200) {
        this.$message.success(res.msg || "导入成功!");
        if(res.msg1){
          this.$message.success(res.msg1);
        }
        this.changeTab(this.tabIndex);
      }
      this.fileList = [];
      this.uploadLoading = false;
    },

    async batchFn(order_field, order_type) {
      this.batchDialog = true;
      this.batchLoading = true;

      this.getModelListFn(true);
      this.getOrgListFn(true)

      let res = await getBatchStats({
        ...this.seekForm2,
        order_field: order_field || 'create_time',
        order_type: order_type || 'desc'
      });

      this.batchList = (res || []).map((obj) => {
        return {
          ...obj,
          removeLoading: false,
        };
      });

      this.batchLoading = false;
    },

    async removeBatchFn(row) {
      this.$confirm("此操作将永久删除该数据, 是否继续?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(async () => {
          if (row){
            row.removeLoading = true;

            let res = await getBatchDelete({
              batch_nos: row.batch_no,
            });

            this.$message.success("删除成功!");

            this.batchFn();
            this.changeTab(this.tabIndex);
            row.removeLoading = false;
          } else {
            this.removeMoreLoading = true;

            let res = await getBatchDelete({
              batch_nos: this.multipleSelection.map(obj=> obj.batch_no).toString(),
            });

            this.$message.success("批量删除成功!");

            this.batchFn();
            this.changeTab(this.tabIndex);
            this.removeMoreLoading = false;
          }
          
        })
        .catch(() => {});
    },

    async settingFn() {
      this.modelDialog = true;
      this.dialogLoading2 = true;

      let res = await getModelList();

      this.modelList = res || [];
      this.seekForm1 = {
        modelName: res[0].model_name,
      };

      this.getModelConfigFn();
    },

    async getModelConfigFn() {
      this.dialogLoading2 = true;
      let res1 = await getModelConfig({
        model_name: this.seekForm1.modelName || "",
      });

      this.seekForm1 = {
        ...this.seekForm1,
        modelType: (res1.type_code || "") + "",
      };
      this.modelTableObj = res1 || {};
      this.modelTableList = (res1.data || []).map((obj) => {
        let str = Object.keys(obj).reduce((a, b) =>
          a.length < b.length ? a : b
        );
        return {
          modelAttrName: str,
          model_name: obj[str],
          model_name_des: obj[`${str}_des`],
          model_name_disable: obj[`${str}_disable`],
        };
      });
      this.dialogLoading2 = false;
    },

    async settingConfirmFn() {
      this.$refs.modelConfig.validate(async (valid) => {
        if (valid) {
          this.dialogLoading2 = true;

          let allObj = {};
          this.modelTableObj.data.forEach((obj) => {
            allObj = {
              ...allObj,
              ...obj,
            };
          });

          let params = {
            id: this.modelTableObj.id,
            type_code: this.seekForm1.modelType,
            type_des: this.modeTypelList.find(
              (obj) => obj.value == this.seekForm1.modelType
            ).label,
          };
          Object.keys(allObj).forEach((key) => {
            let beforeStr = key.split("_", 2)[0];
            let afterStr = key.split("_", 2)[1] || "";

            if (key.indexOf("model_name") != -1) {
              beforeStr = "model_name";
              afterStr = key.split("model_name", 2)[1] || "";

              params[key] = this.modelTableList.find(
                (item) => item["modelAttrName"] == beforeStr
              )[`model_name${afterStr}`];
            } else {
              params[key] = this.modelTableList.find(
                (item) => item["modelAttrName"] == beforeStr
              )[`model_name${afterStr ? "_" + afterStr : ""}`];
            }
          });

          let res = await getModelConfigUpd(params);

          this.$message.success("修改成功!");

          this.dialogLoading2 = false;
        } else {
          this.$message.warning("请选择模型类别");
        }
      });
    },

    async getDataAllFn() {
      this.arrLoading1 = true;
      let res = [];
      let params = {
        // month: this.dataTime.replace("/", ""),
        ...this.getParams(this.dataTime),
      };
      if (this.tabIndex == 1) {
        res = await getDataAll(params);
      }
      if (this.tabIndex == 2) {
        params = this.getParams(this.dataTimeArr);
        res = await getDataMonthlyAll(params);
      }

      this.arr1 = res || [];
      this.arrLoading1 = false;
    },

    async downDetail(code, row, name) {
      if (this.tabIndex == 1) {
        this.getChartDataFn(code, row, name);
      } else {
        this.downDetailLoading = true;
        this.dialogVisible = true;
        this.dialogIndex = code + 1;
        this.dialogName = name;

        this.downDetailParams = {
          typeCode: code,
          ...this.getParams(this.dataTimeArr),
          jgbm: row ? row["机构编码"] : undefined,
        };

        let res = await getChartDataMonthly(this.downDetailParams);

        this.dialogArr = res || [];
        this.downDetailLoading = false;
      }
    },

    async getChartDataFn(code, row, name) {
      if (row) {
        this.downDetailLoading = true;
        this.dialogVisible = true;
        this.dialogIndex = code + 1;
        this.dialogName = name;
      } else {
        this[`arrLoading${code + 1}`] = true;
      }

      this.downDetailParams = {
        typeCode: code,
        // month: this.dataTime.replace("/", ""),
        ...this.getParams(this.dataTime),
        jgbm: row ? row["机构编码"] : undefined,
      };
      let res = await getChartData(this.downDetailParams);

      if (row) {
        this.dialogArr = res || [];
        this.downDetailLoading = false;
      } else {
        this[`arr${code + 1}`] = res;
        this[`arrLoading${code + 1}`] = false;
        if (this.dialogVisible) {
          this.dialogArr = this[`arr${this.dialogIndex}`];
        }
      }
    },

    async getChartDataMonthlyFn(code) {
      this[`arrLoading${code + 1}`] = true;
      let res = await getChartDataMonthly({
        typeCode: code,
        ...this.getParams(this.dataTimeArr),
      });
      this[`arr${code + 1}`] = res;
      setTimeout(()=>{
        this[`arrLoading${code + 1}`] = false;
      },200)

      if (this.dialogVisible) {
        this.dialogArr = this[`arr${this.dialogIndex}`];
      }
    },
    async getOrgTypeStatsFn() {
      this.tableLoading = true;
      let res = [];
      let params = {
        // month: this.dataTime.replace("/", ""),
        ...this.getParams(this.dataTime),
      };
      if (this.tabIndex == 1) {
        res = await getOrgTypeStats(params);
      }
      if (this.tabIndex == 2) {
        params = this.getParams(this.dataTimeArr);
        res = await getOrgTypeStats2(params);
      }

      this.tableData = res || [];
      this.tableLoading = false;
    },

    async getExportFn() {
      this.exportLoading = true;
      let timeStr =
        (this.seekForm.time[0] || "").replace("-", "") +
        " " +
        (this.seekForm.time[1] || "").replace("-", "");
      let orgName = this.seekForm.orgId
        ? this.orgList.find((obj) => obj.jgbm == this.seekForm.orgId).jgmc
        : "";
      let res = await getExport(this.getDetailParams);

      try {
        // 创建下载链接
        const url = window.URL.createObjectURL(
          new Blob([res], {
            type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
          })
        );
        const link = document.createElement("a");
        link.href = url;
        link.download = `${this.dialogName1} ${timeStr} ${orgName}.xlsx`; // 文件名
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url); // 释放内存
        this.$message.success("导出成功!");
      } catch (error) {}

      this.exportLoading = false;
    },

    currentChange(val) {
      this.pageNum = val;
      this.getDetailFn();
    },

    sizeChange(val) {
      this.pageSize = val;
      this.getDetailFn();
    },

    async getDetailFn() {
      this.dialogShow = true;

      this.dialogLoading1 = true;
      let res = await getDetail(this.getDetailParams);

      this.detailHeader = (res.headers || []).filter((obj) => obj);
      let arr = res.data || [];
      let dataArr = [];
      arr.forEach((item, index) => {
        let object = {};
        this.detailHeader.forEach((obj, code) => {
          object[`KPI_VAL${code}`] = item[code];
        });
        dataArr.push(object);
      });

      this.detailArr = dataArr;
      this.total = res.total || 0;

      this.dialogLoading1 = false;
    },

    async getModelListFn(allFlag) {
      this.dialogLoading1 = true;
      let params = { typeCode: this.dialogIndex - 1 };
      if (allFlag){
        params = {}
      }
      let res = await getModelList(params);

      if (allFlag){
        this.modelAllList = res || []
      } else {
        this.modelList = res || [];

      this.getOrgListFn();
      this.getDetailFn();
      }
      
    },

    async getOrgListFn(allFlag) {
      let params = { modelName: this.dialogName1 };
      if (allFlag){
        params = {}
      }

      let res = await getOrgList(params);

      if (allFlag){
        this.orgAllList = res || []
      } else {
        this.orgList = res || [];
      }
      
    },

    changeModel() {
      this.dialogName1 = this.seekForm.modelName;
      this.total = 0;
      this.pageNum = 1;
      this.pageSize = 20;

      this.seekForm = {
        ...this.seekForm,
        jgbm: "",
      };
      this.getOrgListFn();
      this.getDetailFn();
    },

    getParams(arr) {
      return {
        startDate: arr[0].replace("/", "") + "01",
        endDate:
          arr[1].replace("/", "") +
          this.getLastDayOfMonth(
            arr[1].substring(0, 4),
            arr[1].substring(5, 7)
          ),
      };
    },

    getLastDayOfMonth(year, month) {
      const date = new Date(year, month, 0);
      return date.getDate();
    },

    getDateTimeFn(flag) {
      let now = new Date();

      this.dateStr = now
        .toLocaleDateString()
        .split("/")
        .map((part) => part.padStart(2, "0"))
        .join("-");
      this.dateWeek = now.toLocaleDateString("zh-CN", { weekday: "long" });
      this.dateTime = now.toLocaleTimeString();

      if (flag) {
        const halfYearAgo = new Date(now);

        // 设置月份为当前月份减6
        halfYearAgo.setMonth(halfYearAgo.getMonth() - 6);

        // 格式化输出
        const formattedDate = halfYearAgo
          .toISOString()
          .split("T")[0]
          .substring(0, 7)
          .replace("-", "/");

        let endStr = this.dateStr.substring(0, 7).replace("-", "/");
        this.dataTimeArr = [formattedDate, endStr];
        this.dataTime = [formattedDate, endStr];
      }
    },

    dialogClose1() {
      this.seekForm = {};
      this.dialogName1 = "";
      this.detailArr = [];
      this.total = 0;
      this.pageNum = 1;
      this.pageSize = 20;

      this.modelselect = "";
      this.modelTableList = [];
      this.modelTableObj = {};

      this.batchList = [];
      this.batchLoading = false;
      this.$refs.modelConfig && this.$refs.modelConfig.clearValidate();

      this.multipleSelection = [];
      this.seekForm2 = {};
    },

    changeTab(code) {
      this.tabIndex = code;
      this.getDataAllFn();
      // 切换
      if (code == 1) {
        this.getChartDataFn(1);
        this.getChartDataFn(2);
        this.getChartDataFn(3);
        this.getChartDataFn(4);
        this.getChartDataFn(5);
      } else {
        this.getChartDataMonthlyFn(1);
        this.getChartDataMonthlyFn(2);
        this.getChartDataMonthlyFn(3);
        this.getChartDataMonthlyFn(4);
        this.getChartDataMonthlyFn(5);
      }

      this.getOrgTypeStatsFn();
      if (this.dialogShow) {
        this.seekForm = {
          ...this.seekForm,
          time: JSON.parse(JSON.stringify(this.dataTime)),
        };

        this.getDetailFn();
      }
    },

    finished(refStr, dataArr, name, flag) {
      let myChart = this.$refs[refStr].getEchart();
      let that = this;

      myChart.getZr().off("click");
      myChart.getZr().on("click", function (obj) {
        const pointInPixel = [obj.offsetX, obj.offsetY];
        if (!!!myChart.containPixel("grid", pointInPixel)) {
          return;
        }

        // 详细弹窗下钻
        if (flag) {
          var xIndex = myChart.convertFromPixel({ seriesIndex: 0 }, [
            obj.offsetX,
            obj.offsetY,
          ])[0];

          let dataObj = {};
          if (that.tabIndex == 1) {
            dataObj = that.dialogArr[xIndex];
          } else {
            console.log(that.dialogArr);

            dataObj = that.dialogArr[xIndex].data[0];
          }

          that.dialogName1 = dataObj.model_name;

          that.seekForm = {
            ...that.seekForm,
            time: that.tabIndex == 1 ? that.dataTime : that.dataTimeArr,
            modelName: dataObj.model_name,
            orgId: that.downDetailParams.jgbm || "",
          };

          that.getModelListFn();
        } else if (dataArr && dataArr.length > 0) {
          if (that.tabIndex != 1 || name != "总览") {
            that.dialogVisible = true;
            that.dialogIndex = refStr.slice(-1);
            that.dialogArr = dataArr;
            that.dialogName = name;
          }
        }
      });
    },
    dialogClose() {
      this.dialogName = "";
      this.dialogArr = [];
      this.downDetailLoading = false;
      this.downDetailParams = {};
    },

    getPieOptions(dataArray) {
      let centerArr = ["15%", "50%"];
      let itemGap = 10;

      if (window.screen.width >= 1910) {
        centerArr = ["24%", "50%"];
        itemGap = 20;
      }

      let dataArr = dataArray.map((obj) => {
        return {
          name: obj.typeDes,
          value: obj.count,
        };
      });
      let option = {
        tooltip: {
          trigger: "item",
        },
        legend: {
          top: "center",
          right: "0%",
          itemGap: itemGap,
          orient: "vertical",
          textStyle: {
            color: "#ffffff",
          },
          // 使用 formatter 来自定义图例内容
          formatter: function (name) {
            var total = 0;
            var targetData;
            // 遍历所有系列数据以计算总数
            option.series.forEach(function (series) {
              if (series.type === "pie") {
                series.data.forEach(function (data) {
                  if (data.name === name) {
                    targetData = data;
                  }
                  total += data.value || 0;
                });
              }
            });
            var percent =
              total == 0
                ? "0%"
                : ((targetData.value / total) * 100).toFixed(2) + "%";
            return name + "   " + targetData.value + "（" + percent + "）";
          },
        },
        series: [
          {
            type: "pie",
            radius: ["40%", "60%"],
            center: centerArr,
            avoidLabelOverlap: false,
            padAngle: 5,
            itemStyle: {
              borderRadius: 4,
            },
            label: {
              show: false,
              position: "center",
            },
            labelLine: {
              show: false,
            },
            data: dataArr,
          },
        ],
      };

      return option;
    },

    getBarOptions(dataArray, indexCode, flag) {
      let colorRgbStr = "27, 126, 242";
      if (indexCode == "2") {
        colorRgbStr = "27, 126, 242";
      } else if (indexCode == "3") {
        colorRgbStr = "255, 184, 0";
      } else if (indexCode == "4") {
        colorRgbStr = "0, 221, 181";
      } else if (indexCode == "5") {
        colorRgbStr = "255, 0, 92";
      } else if (indexCode == "6") {
        colorRgbStr = "123, 101, 255";
      }
      const VALUE = dataArray.map((one) => one.count);
      const NAMES = dataArray.map((one) => one.model_name);

      // 绘制左侧面
      const CubeLeft = this.$echarts.graphic.extendShape({
        shape: {
          x: 0,
          y: 0,
        },
        buildPath: function (ctx, shape) {
          const xAxisPoint = shape.xAxisPoint;
          const c0 = [shape.x + 2, shape.y];
          const c1 = [shape.x - 7, shape.y - 1];
          const c2 = [xAxisPoint[0] - 7, xAxisPoint[1] - 3];
          const c3 = [xAxisPoint[0] + 2, xAxisPoint[1]];
          ctx
            .moveTo(c0[0], c0[1])
            .lineTo(c1[0], c1[1])
            .lineTo(c2[0], c2[1])
            .lineTo(c3[0], c3[1])
            .closePath();
        },
      });
      // 绘制右侧面
      const CubeRight = this.$echarts.graphic.extendShape({
        shape: {
          x: 0,
          y: 0,
        },
        buildPath: function (ctx, shape) {
          const xAxisPoint = shape.xAxisPoint;
          const c1 = [shape.x + 2, shape.y];
          const c2 = [xAxisPoint[0] + 2, xAxisPoint[1]];
          const c3 = [xAxisPoint[0] + 10, xAxisPoint[1] - 5];
          const c4 = [shape.x + 10, shape.y - 5];
          ctx
            .moveTo(c1[0], c1[1])
            .lineTo(c2[0], c2[1])
            .lineTo(c3[0], c3[1])
            .lineTo(c4[0], c4[1])
            .closePath();
        },
      });
      // 绘制顶面
      const CubeTop = this.$echarts.graphic.extendShape({
        shape: {
          x: 0,
          y: 0,
        },
        buildPath: function (ctx, shape) {
          const c1 = [shape.x + 2, shape.y + 3];
          const c2 = [shape.x + 10, shape.y - 5]; //右点
          const c3 = [shape.x - 0, shape.y - 7];
          const c4 = [shape.x - 7, shape.y - 1];
          ctx
            .moveTo(c1[0], c1[1])
            .lineTo(c2[0], c2[1])
            .lineTo(c3[0], c3[1])
            .lineTo(c4[0], c4[1])
            .closePath();
        },
      });
      // 注册三个面图形
      this.$echarts.graphic.registerShape("CubeLeft", CubeLeft);
      this.$echarts.graphic.registerShape("CubeRight", CubeRight);
      this.$echarts.graphic.registerShape("CubeTop", CubeTop);

      let endStr = 100;
      if (flag) {
        endStr = 100;
      }

      return {
        backgroundColor: "transparent",
        dataZoom: [
          {
            type: "inside",
            throttle: "80",
            minValyeSpan: 5,
            start: 0,
            end: endStr,
            zoomLock: false,
          },
        ],
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow",
          },
          formatter: function (params) {
            const item = params[0];
            return item.name + " : " + item.value;
          },
        },
        grid: {
          left: 20,
          top: 15,
          bottom: 15,
          right: 20,
          containLabel: true,
        },
        xAxis: {
          offset: 6,
          type: "category",
          data: NAMES,
          axisLabel: {
            color: "#ffffff",
            margin: 15,
          },
          splitLine: {
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
          axisLine: {
            show: true,
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
          axisTick: {
            show: false,
          },
          axisLabel: {
            rotate: 0,
            color: "#FFF",
            fontSize: 14,
            formatter: (label) => {
              let text = chunk(((label || "").substr(0, 18) || "").split(""), 6)
                .map((one) => one.join(""))
                .join("\n");
              return text;
            },
          },
        },
        yAxis: [
          {
            type: "value",
            axisLine: {
              show: false,
              lineStyle: {
                color: "#7ebaf2",
              },
            },
            splitLine: {
              lineStyle: {
                color: "rgba(255,255,255,0.2)",
              },
            },
            axisTick: {
              show: false,
            },
            splitNumber: 4,
            axisLabel: {
              fontSize: 14,
              color: "#FFF",
              margin: 15,
            },
          },
        ],
        series: [
          {
            type: "custom",
            renderItem: (params, api) => {
              let cubeLeftStyle = "";
              let cubeRightStyle = "";
              let cubeTopStyle = "";
              // 颜色
              cubeLeftStyle = new this.$echarts.graphic.LinearGradient(
                0,
                0,
                0,
                1,
                [
                  {
                    offset: 0,
                    color: `rgba(${colorRgbStr}, 0.8)`,
                  },
                  {
                    offset: 0.5,
                    color: `rgba(${colorRgbStr}, 0.6)`,
                  },
                  {
                    offset: 0.8,
                    color: `rgba(${colorRgbStr}, 0.3)`,
                  },
                  {
                    offset: 1,
                    color: `rgba(${colorRgbStr}, 0.1)`,
                  },
                ]
              );
              cubeRightStyle = new this.$echarts.graphic.LinearGradient(
                0,
                0,
                0,
                1,
                [
                  {
                    offset: 0,
                    color: `rgba(${colorRgbStr}, 0.8)`,
                  },
                  {
                    offset: 0.5,
                    color: `rgba(${colorRgbStr}, 0.6)`,
                  },
                  {
                    offset: 0.8,
                    color: `rgba(${colorRgbStr}, 0.3)`,
                  },
                  {
                    offset: 1,
                    color: `rgba(${colorRgbStr}, 0.1)`,
                  },
                ]
              );
              cubeTopStyle = new this.$echarts.graphic.LinearGradient(
                0,
                0,
                0,
                1,
                [
                  {
                    offset: 0,
                    color: `rgba(${colorRgbStr}, 1)`,
                  },
                  {
                    offset: 1,
                    color: `rgba(${colorRgbStr}, 1)`,
                  },
                ]
              );
              //颜色end
              const location = api.coord([api.value(0), api.value(1)]);
              return {
                type: "group",
                children: [
                  {
                    type: "CubeLeft",
                    shape: {
                      api,
                      xValue: api.value(0),
                      yValue: api.value(1),
                      x: location[0],
                      y: location[1],
                      xAxisPoint: api.coord([api.value(0), 0]),
                    },
                    style: {
                      fill: cubeLeftStyle,
                    },
                  },
                  {
                    type: "CubeRight",
                    shape: {
                      api,
                      xValue: api.value(0),
                      yValue: api.value(1),
                      x: location[0],
                      y: location[1],
                      xAxisPoint: api.coord([api.value(0), 0]),
                    },
                    style: {
                      fill: cubeRightStyle,
                    },
                  },
                  {
                    type: "CubeTop",
                    shape: {
                      api,
                      xValue: api.value(0),
                      yValue: api.value(1),
                      x: location[0],
                      y: location[1],
                      xAxisPoint: api.coord([api.value(0), 0]),
                    },
                    style: {
                      fill: cubeTopStyle,
                    },
                  },
                ],
              };
            },
            data: VALUE,
          },
        ],
      };
    },

    getLineOptions(dataArray, flag) {
      let nameArr = [],
        dataArr = [],
        dateArr = [];

      if (dataArray.length > 0 && dataArray[0].data) {
        nameArr = dataArray[0].data.map((obj) => obj.typeDes || obj.model_name);
        dateArr = dataArray.map((obj) => obj.month);

        nameArr.forEach((item, index) => {
          dataArr[index] = {
            name: item,
            type: "line",
            data: [],
          };
          dataArr[index].data = dataArray.map((obj) => {
            return obj.data[index].count;
          });
        });
      }

      let legendType = "plain";
      let endStr = 100;
      if (!flag) {
        legendType = "scroll";
        endStr = 100;
      }

      return {
        animationDuration: 0,
        dataZoom: [
          {
            type: "inside",
            throttle: "80",
            minValyeSpan: 5,
            start: 0,
            end: endStr,
            zoomLock: false,
          },
        ],
        tooltip: {
          trigger: "axis",
          confine: true,
          extraCssText: "max - width: none; overflow: visible;",
        },
        legend: {
          orient: "horizontal",
          type: legendType,
          top: "0%",
          data: nameArr,
          textStyle: {
            color: "#fff",
          },
          pageTextStyle: {
            color: "#fff",
          },
          pageIconColor: "#666666",
          pageIconInactiveColor: "#fff",
        },
        grid: {
          top: "20%",
          left: "3%",
          right: "8%",
          bottom: "5%",
          containLabel: true,
        },
        xAxis: {
          type: "category",
          boundaryGap: false,
          data: dateArr,
          axisLabel: {
            color: "#ffffff",
            fintSize: 14,
            margin: 15,
          },
          axisLine: {
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
          splitLine: {
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
        },
        yAxis: {
          type: "value",
          nameGap: 10,
          axisLabel: {
            color: "#ffffff",
            margin: 15,
            fintSize: 14,
          },
          splitLine: {
            lineStyle: {
              color: "rgba(255,255,255,0.2)",
            },
          },
        },
        series: dataArr,
      };
    },
  },
};
</script>


